from pptx import Presentation

# Load the processed presentation
prs = Presentation('/root/Awesome-Agent-Papers_processed.pptx')

print(f"Total slides in processed file: {len(prs.slides)}\n")

# Verify each slide
for slide_idx, slide in enumerate(prs.slides, 1):
    print(f"Slide {slide_idx}:")

    for shape in slide.shapes:
        if hasattr(shape, "text") and shape.text.strip():
            text = shape.text.strip()[:70]
            print(f"  - {text}")

            if hasattr(shape, "text_frame"):
                for paragraph in shape.text_frame.paragraphs:
                    for run in paragraph.runs:
                        if run.text.strip():
                            print(f"    Font: {run.font.name}, Size: {run.font.size}, Bold: {run.font.bold}, Color: {run.font.color.rgb if hasattr(run.font.color, 'rgb') else 'N/A'}")
                            break
                    break

